fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let was: i32 = host::display::state_get(2);
    host::display::state_set(2, down);
    if down == 1 && was == 0 {
        let head: i32 = host::display::state_get(1);
        host::display::state_set(8 + head * 3, host::display::pointer_x());
        host::display::state_set(9 + head * 3, host::display::pointer_y());
        host::display::state_set(10 + head * 3, t + 1);
        host::display::state_set(1, (head + 1) % 4);
    }
    host::display::clear(0x000014);
    let mut r: i32 = 0;
    while r < 4 {
        let birth: i32 = host::display::state_get(10 + r * 3);
        if birth > 0 {
            let age: i32 = t + 1 - birth;
            if age < 90 {
                let cx: i32 = host::display::state_get(8 + r * 3);
                let cy: i32 = host::display::state_get(9 + r * 3);
                let blue: i32 = 255 - age * 2;
                let c: i32 = blue / 2 * 256 + blue;
                let mut k: i32 = 0;
                while k < 32 {
                    let x: i32 = cx + tab[k] * age / 127;
                    let y: i32 = cy + tab[(k + 8) & 31] * age / 127;
                    host::display::fill_rect(x, y, 2, 2, c);
                    k = k + 1;
                }
            }
        }
        r = r + 1;
    }
    host::display::present();
}
